// Convierte la respuesta con forma fija del scout en una página.

// Todo texto que viene de afuera pasa por acá antes de entrar al HTML.
function esc(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}
// Solo enlaces web de verdad.
function enlaceSeguro(url) {
  return /^https?:\/\//i.test(String(url || '')) ? String(url) : ''
}
function enlace(url, texto) {
  const u = enlaceSeguro(url)
  return u ? '<a href="' + esc(u) + '" target="_blank" rel="noopener">' + esc(texto) + '</a>' : esc(texto)
}
function lista(x) {
  return Array.isArray(x) ? x.filter(function (e) { return e && typeof e === 'object' }) : []
}
// Estilos de la charla. Cada propiedad va en su propia regla.
function css(reglas) {
  return Object.keys(reglas).map(function (sel) {
    return Object.keys(reglas[sel]).map(function (prop) {
      return sel + '{' + prop + ':' + reglas[sel][prop] + '}'
    }).join('')
  }).join('')
}
const estilo = css({
  'html, body': { 'background': '#070A0F', 'margin': '0' },
  'body': { 'color': '#F5F7FF', 'font-family': '"Segoe UI", system-ui, sans-serif', 'font-weight': '700', 'font-size': '22px', 'line-height': '1.4', 'display': 'block' },
  '.hoja': { 'max-width': '720px', 'margin': '0 auto', 'padding': '48px 24px' },
  '.hoja p': { 'margin': '0 0 12px 0', 'font-size': '22px' },
  '.hoja .rotulo': { 'color': '#9AA3B8', 'margin': '0 0 8px 0' },
  '.hoja h1': { 'font-size': '44px', 'line-height': '1.15', 'margin': '0 0 8px 0' },
  '.hoja h2': { 'font-size': '30px', 'color': '#FFB547', 'margin': '40px 0 12px 0' },
  '.hoja ul': { 'margin': '0', 'padding': '0 0 0 28px' },
  '.hoja li': { 'margin': '0 0 14px 0' },
  '.hoja .apoyo': { 'color': '#9AA3B8', 'font-size': '22px' },
  '.hoja a': { 'color': '#4DA3FF' },
  '.idea': { 'border': '3px solid #4DA3FF', 'border-radius': '16px', 'padding': '20px 24px', 'margin': '0 0 16px 0' },
  '.idea .numero': { 'color': '#FFB547', 'font-size': '28px', 'margin': '0 0 4px 0' },
  '.idea .paso': { 'color': '#FFB547' }
})

const r = $input.first().json.output || {}
const yaExiste = lista(r.ya_existe).slice(0, 5)
const paraLeer = lista(r.para_leer).slice(0, 5)
const paraVer = lista(r.para_ver).slice(0, 5)
const ideas = lista(r.ideas).slice(0, 3)

let html = '<style>' + estilo + '</style><main class="hoja">'
html += '<p class="rotulo">El scout del reto</p>'
html += '<h1>' + esc(r.reto_en_una_frase) + '</h1>'
if (yaExiste.length) {
  html += '<h2>Ya existe</h2><ul>' + yaExiste.map(function (e) {
    return '<li>' + enlace(e.enlace, e.nombre) + (e.que_es ? '<br><span class="apoyo">' + esc(e.que_es) + '</span>' : '') + '</li>'
  }).join('') + '</ul>'
}
if (paraLeer.length) {
  html += '<h2>Para leer</h2><ul>' + paraLeer.map(function (e) {
    return '<li>' + enlace(e.enlace, e.titulo) + '</li>'
  }).join('') + '</ul>'
}
if (paraVer.length) {
  html += '<h2>Para ver</h2><ul>' + paraVer.map(function (e) {
    return '<li>' + enlace(e.enlace, e.titulo) + (e.canal ? '<br><span class="apoyo">' + esc(e.canal) + '</span>' : '') + '</li>'
  }).join('') + '</ul>'
}
if (ideas.length) {
  html += '<h2>Tres ideas para el fin de semana</h2>' + ideas.map(function (e, i) {
    return '<div class="idea"><p class="numero">' + (i + 1) + '. ' + esc(e.nombre) + '</p>' +
      '<p>' + esc(e.que_hace) + '</p>' +
      '<p><span class="paso">Esta noche:</span> ' + esc(e.primer_paso) + '</p></div>'
  }).join('')
}
html += '</main>'
return [{ json: { html: html, ya_existe: yaExiste.length, para_leer: paraLeer.length, para_ver: paraVer.length, ideas: ideas.length } }]
